#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <queue>
#include <functional>
#include <utility>
using namespace std;
int main(){int n,C;cin>>n>>C;vector<long long>dp(C+1);for(int i=0;i<n;++i){int w,q;long long v;cin>>w>>v>>q;for(int block=1;q>0;block*=2){int take=min(block,q);q-=take;int weight=w*take;long long value=v*take;for(int c=C;c>=weight;--c)dp[c]=max(dp[c],dp[c-weight]+value);}}cout<<dp[C]<<'\n';}
